glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1.0);
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform Constant {
  vec4 mainColor;
  vec4 params;
  vec4 params2;
};
#define TAU 6.28318530718
#define PI  3.14159265359
float hash21(vec2 p){ p=fract(p*vec2(123.34,456.21)); p+=dot(p,p+45.32); return fract(p.x*p.y); }
float vnoise(vec2 p){ vec2 i=floor(p),f=fract(p); vec2 u=f*f*(3.0-2.0*f);
  return mix(mix(hash21(i),hash21(i+vec2(1.0,0.0)),u.x),mix(hash21(i+vec2(0.0,1.0)),hash21(i+vec2(1.0,1.0)),u.x),u.y); }
float fbm(vec2 p){ float v=0.0,a=0.5; for(int i=0;i<4;i++){v+=a*vnoise(p);p*=2.0;a*=0.5;} return v; }
vec3 ACES(vec3 x){ const float a=2.51,b=0.03,c=2.43,d=0.59,e=0.14; return clamp((x*(a*x+b))/(x*(c*x+d)+e),0.0,1.0); }
float sdRoundBox(vec2 p, vec2 b, float r){ vec2 q=abs(p)-b+r; return min(max(q.x,q.y),0.0)+length(max(q,0.0))-r; }
const vec3 C_GOLD =vec3(0.98,0.82,0.50);
const vec3 C_WGOLD=vec3(1.00,0.94,0.78);
const vec3 C_ROSE =vec3(1.00,0.46,0.62);
const vec3 C_VIO  =vec3(0.62,0.44,0.96);
vec4 frag () {
  vec2 p = uv0*2.0-1.0;
  float aspect = params2.x;
  vec2 ps = vec2(p.x*aspect, p.y);
  float t = cc_time.x;
  float flameAmt=params.x, flickAmt=params.y, innerAmt=params.z, rad=params.w;
  vec2 b = vec2(0.71*aspect, 0.71);
  float d = sdRoundBox(ps, b, rad);
  float ang = atan(ps.y, ps.x); float param = (ang+PI)/TAU;
  float warp  = fbm(vec2(param*12.0 + 3.0*fbm(vec2(param*6.0, t*0.6)), t*1.2));
  float flick = mix(1.0, 0.4+1.0*fbm(vec2(param*26.0 - t*2.6, t*1.9)), flickAmt);
  float tongueH = 0.02 + flameAmt*(0.35 + 1.6*warp);
  float prof = (d < 0.0) ? exp(d/0.022) : exp(-d/tongueH);
  float outer = prof * flick;
  float edge  = exp(-abs(d)/0.010);
  float hgt = clamp(max(d,0.0)/(tongueH*1.6), 0.0, 1.0);
  vec3 fcol = (hgt<0.5) ? mix(C_WGOLD, C_ROSE, smoothstep(0.0,0.5,hgt))
                        : mix(C_ROSE,  C_VIO,  smoothstep(0.5,1.0,hgt));
  vec3 col = fcol*outer*1.1 + C_WGOLD*edge*0.55;
  col += C_GOLD * exp(d/0.05) * step(d,0.0) * innerAmt;
  col = ACES(col * mainColor.a);
  col = mix(col, col*mainColor.rgb*1.12, 0.12);
  float a = clamp(max(col.r,max(col.g,col.b))*1.5, 0.0, 1.0);
  return vec4(col, a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

